22	namespace llm {
23	namespace {
24	constexpr const char LLM_OPTION_RDMA_TRAFFIC_CLASS[] = "llm.RdmaTrafficClass";
25	constexpr const char LLM_OPTION_RDMA_SERVICE_LEVEL[] = "llm.RdmaServiceLevel";
26	constexpr const char ADXL_OPTION_LOCAL_COMM_RES[] = "adxl.LocalCommRes";
27	}  // namespace
28	
29	void HixlTransferEngine::LLMDataDist2HixlOptions(
30	    const std::map<ge::AscendString, ge::AscendString> &llm_datdsist_options,
31	    std::map<ge::AscendString, ge::AscendString> &hixl_options) {
32	  const static std::map<ge::AscendString, ge::AscendString> llm_to_hixl_options = {
33	      {LLM_OPTION_RDMA_TRAFFIC_CLASS, hixl::OPTION_RDMA_TRAFFIC_CLASS},
34	      {LLM_OPTION_RDMA_SERVICE_LEVEL, hixl::OPTION_RDMA_SERVICE_LEVEL},
35	      {llm_datadist::OPTION_LOCAL_COMM_RES, ADXL_OPTION_LOCAL_COMM_RES},
36	      {llm_datadist::OPTION_GLOBAL_RESOURCE_CONFIG, hixl::OPTION_GLOBAL_RESOURCE_CONFIG},
37	  };
38	  for (const auto &option : llm_datdsist_options) {
39	    const auto &iter = llm_to_hixl_options.find(option.first);
40	    if (iter != llm_to_hixl_options.cend()) {
41	      hixl_options[iter->second] = option.second;
42	    } else {
43	      LLMLOGI("Option:%s is not supported by HIXL, will be ignored.", option.first.GetString());
44	    }
45	  }
46	}
47	
48	ge::Status HixlTransferEngine::InitMsgProcessor() {
49	  hixl::CtrlMsgPlugin::Initialize();
50	  hixl::CallbackProcessor callback = [this](int32_t fd, const char *msg, uint64_t msg_len,
51	                                            bool &keep_fd) -> hixl::Status {
52	    (void)msg;
53	    (void)msg_len;
54	    keep_fd = false;
55	    CacheTableInfo cache_table_info{};
56	    const auto &buffer_and_size = cache_manager_->GetCacheTableBufferAndSize();
57	    cache_table_info.cache_table_addr = PtrToValue(buffer_and_size.first);
58	    cache_table_info.cache_table_size = buffer_and_size.second;
59	    hixl::CtrlMsgHeader header{};
60	    header.magic = hixl::kMagicNumber;
61	    header.body_size = static_cast<uint64_t>(sizeof(hixl::CtrlMsgType) + sizeof(CacheTableInfo));
62	    hixl::CtrlMsgType msg_type = hixl::CtrlMsgType::kGetCacheTableResp;
63	    HIXL_CHK_STATUS_RET(hixl::CtrlMsgPlugin::Send(fd, &header, static_cast<uint64_t>(sizeof(header))),
64	                        "Failed to send cache table msg header");
65	    HIXL_CHK_STATUS_RET(hixl::CtrlMsgPlugin::Send(fd, &msg_type, static_cast<uint64_t>(sizeof(msg_type))),
66	                        "Failed to send cache table msg type");
67	    HIXL_CHK_STATUS_RET(hixl::CtrlMsgPlugin::Send(fd, &cache_table_info, static_cast<uint64_t>(sizeof(CacheTableInfo))),
68	                        "Failed to send cache table msg body");
69	    return hixl::SUCCESS;
70	  };
71	  LLM_CHK_HIXL_RET(
72	      engine_->RegisterCallbackProcessor(static_cast<int32_t>(hixl::CtrlMsgType::kGetCacheTableReq), callback),
73	      "Failed to initialize Hixl engine.");
74	  return ge::SUCCESS;
75	}
76	
77	ge::Status HixlTransferEngine::Initialize(const std::map<ge::AscendString, ge::AscendString> &options) {
78	  bool remote_cache_accessible = false;
79	  LLM_CHK_STATUS_RET(LLMUtils::ParseFlag(kLlmOptionEnableRemoteCacheAccessible, options, remote_cache_accessible),
80	                     "Failed to parse option %s", kLlmOptionEnableRemoteCacheAccessible);
81	  LLM_CHK_BOOL_RET_STATUS(remote_cache_accessible, ge::LLM_PARAM_INVALID,
82	                          "When using hixl backend, option:%s needs to be specified to true.",
83	                          kLlmOptionEnableRemoteCacheAccessible);
84	
85	  const auto &port_iter = options.find(kLlmOptionListenPort);
86	  const auto &ip_iter = options.find(kLlmOptionListenIp);
87	  LLM_CHK_BOOL_RET_STATUS(port_iter != options.cend() && ip_iter != options.cend(), ge::LLM_PARAM_INVALID,
88	                          "When using hixl backend, option:%s needs to be specified.",
89	                          llm_datadist::OPTION_LISTEN_IP_INFO);
90	  std::string ip = ip_iter->second.GetString();
91	  uint32_t port = 0U;
92	  LLM_CHK_STATUS_RET(LLMUtils::ToNumber(port_iter->second.GetString(), port), "Option %s is invalid: [%s]",
93	                     kLlmOptionListenPort, port_iter->second.GetString());
94	  local_engine_ = ip + ":" + std::to_string(port);
95	  LLMLOGI("listen option %s=%s", llm_datadist::OPTION_LISTEN_IP_INFO, local_engine_.c_str());
96	  LLM_ASSERT_RT_OK(aclrtGetCurrentContext(&rt_context_));
97	  std::map<ge::AscendString, ge::AscendString> hixl_options{};
98	  hixl_options[hixl::OPTION_BUFFER_POOL] = "0:0";
99	  LLMDataDist2HixlOptions(options, hixl_options);
100	  hixl::HixlOptions parsed_options;
101	  engine_ = hixl::EngineFactory::CreateEngine(local_engine_, hixl_options, parsed_options);
102	  LLM_CHECK_NOTNULL(engine_);
103	  LLM_CHK_HIXL_RET(engine_->Initialize(parsed_options), "Failed to initialize Hixl engine.");
104	  LLM_CHK_STATUS_RET(InitMsgProcessor(), "Failed to init msg processor");
105	  return ge::SUCCESS;
106	}
107	
108	void HixlTransferEngine::Finalize() {
109	  LLMLOGI("Begin to transfer engine finalize.");
110	  engine_->Finalize();
111	}
112	
113	ge::Status HixlTransferEngine::RegisterMem(void *addr, uint64_t size, CommMemType type, void *&handle) {
114	  hixl::MemDesc desc{};
115	  desc.addr = reinterpret_cast<uintptr_t>(addr);
116	  desc.len = size;
117	  hixl::MemType mem_type = type == COMM_MEM_TYPE_HOST ? hixl::MEM_HOST : hixl::MEM_DEVICE;
118	  LLM_CHK_HIXL_RET(engine_->RegisterMem(desc, mem_type, handle), "Failed to register mem, addr:%p, size:%lu, type:%d.",
119	                   addr, size, static_cast<int32_t>(type));
120	  LLMLOGI("Register mem success, addr:%p, size:%lu, type:%d", addr, size, static_cast<int32_t>(type));
121	  return ge::SUCCESS;
122	}
123	
124	ge::Status HixlTransferEngine::UnregisterMem(void *handle) {
125	  LLM_CHK_HIXL_RET(engine_->DeregisterMem(handle), "Failed to deregister mem, handle:%p.", handle);
126	  return ge::SUCCESS;
127	}
128	
129	ge::Status HixlTransferEngine::LinkCluster(const ClusterInfo &cluster, int32_t timeout) {
130	  LLM_CHK_BOOL_RET_STATUS(cluster.remote_ip_infos.size() == 1U, ge::LLM_PARAM_INVALID,
131	                          "remote_ip_infos size != 1 is unsupported.");
132	  std::string remote_ip_str;
133	  LLM_CHK_STATUS_RET(LLMUtils::IntToIp(cluster.remote_ip_infos[0].ip, remote_ip_str), "Failed to convert remote ip.");
134	  uint32_t remote_port = static_cast<uint32_t>(cluster.remote_ip_infos[0].port);
135	  LLMLOGI("Start to link cluster, remote cluster_id:%lu, remote info %s:%u, timeout:%d ms.", cluster.remote_cluster_id,
136	          remote_ip_str.c_str(), remote_port, timeout);
137	  auto entity = llm::MakeShared<HixlEntity>(remote_ip_str, remote_port, engine_.get());
138	  LLM_CHECK_NOTNULL(entity);
139	  auto mem_info_ptr =
140	      MakeUnique<EntityMemInfo>(true, comm_entity_manager_->GetHostRegPool(), comm_entity_manager_->GetDeviceRegPool());
141	  LLM_CHECK_NOTNULL(mem_info_ptr);
142	  LLM_CHK_STATUS_RET(mem_info_ptr->Initialize(), "Failed to init mem info");
143	  entity->SetEntityMemInfo(mem_info_ptr);
144	  entity->SetCacheManager(cache_manager_);
145	  entity->SetContext(rt_context_);
146	  LLM_CHK_STATUS_RET(entity->Initialize(timeout), "Failed to init hixl entity");
147	  ScopeGuard guard([entity]() { entity->Finalize(); });
148	  LLM_CHK_STATUS_RET(entity->SetInfo(), "Failed to set entity info");
149	  entity->MarkEntityIdle();
150	  LLM_CHK_STATUS_RET(comm_entity_manager_->AddEntity(cluster.remote_cluster_id, entity),
151	                     "Failed to create entity, remote_cluster_id:%lu", cluster.remote_cluster_id);
152	  guard.Dismiss();
153	  return ge::SUCCESS;
154	}
155	
156	ge::Status HixlTransferEngine::LinkClusters(const std::vector<ClusterInfo> &clusters, std::vector<ge::Status> &rets,
157	                                            int32_t timeout) {
158	  LLM_CHK_BOOL_RET_STATUS(clusters.size() > 0, ge::LLM_PARAM_INVALID, "clusters size must > 0");
159	  LLMThreadPool thread_pool("llm_link_mem", 16U);
160	  std::vector<std::future<ge::Status>> future_rets;
161	  for (const auto &cluster : clusters) {
162	    auto fut = thread_pool.commit([this, cluster, timeout]() -> ge::Status {
163	      LLM_CHK_BOOL_RET_STATUS(aclrtSetCurrentContext(rt_context_) == ACL_ERROR_NONE, ge::LLM_PARAM_INVALID,
164	                              "Set runtime context failed.");
165	      LLM_CHK_STATUS_RET(LinkCluster(cluster, timeout),
166	                         "Failed to link cluster, remote_cluster_id = %lu, remote_role_type = %d.",
167	                         cluster.remote_cluster_id, cluster.remote_role_type);
168	      return ge::SUCCESS;
169	    });
170	    future_rets.emplace_back(std::move(fut));
171	  }
172	
173	  auto ret = ge::SUCCESS;
174	  for (size_t i = 0; i < future_rets.size(); ++i) {
175	    auto fut_ret = future_rets[i].get();
176	    ret = fut_ret != ge::SUCCESS ? fut_ret : ret;
177	    LLM_CHK_STATUS(fut_ret, "Failed to link clusters, index = %zu", i);
178	    rets.emplace_back(fut_ret);
179	  }
180	  return ret;
181	}
182	
183	ge::Status HixlTransferEngine::UnlinkCluster(const ClusterInfo &cluster, int32_t timeout) const {
184	  LLMLOGI("Start to unlink cluster, remote cluster_id:%lu, timeout:%d ms.", cluster.remote_cluster_id, timeout);
185	  LLM_CHK_STATUS_RET(comm_entity_manager_->DestroyEntity(cluster.remote_cluster_id),
186	                     "Failed to destroy entity, remote_cluster_id:%lu", cluster.remote_cluster_id);
187	  return ge::SUCCESS;
188	}
189	
190	ge::Status HixlTransferEngine::UnlinkClusters(const std::vector<ClusterInfo> &clusters, std::vector<ge::Status> &rets,
191	                                              int32_t timeout, bool force_flag) {
192	  (void)force_flag;
193	  LLM_CHK_BOOL_RET_STATUS(clusters.size() > 0, ge::LLM_PARAM_INVALID, "clusters size must > 0");
194	  LLMThreadPool thread_pool("llm_link_mem", 16U);
195	  std::vector<std::future<ge::Status>> future_rets;
196	  for (const auto &cluster : clusters) {
197	    auto fut = thread_pool.commit([this, cluster, timeout]() -> ge::Status {
198	      LLM_CHK_BOOL_RET_STATUS(aclrtSetCurrentContext(rt_context_) == ACL_ERROR_NONE, ge::LLM_PARAM_INVALID,
199	                              "Set runtime context failed.");
200	      LLM_CHK_STATUS_RET(UnlinkCluster(cluster, timeout),
201	                         "Failed to unlink cluster, remote_cluster_id = %lu, remote_role_type = %d.",
202	                         cluster.remote_cluster_id, cluster.remote_role_type);
203	      return ge::SUCCESS;
204	    });
205	    future_rets.emplace_back(std::move(fut));
206	  }
207	
208	  auto ret = ge::SUCCESS;
209	  for (size_t i = 0; i < future_rets.size(); ++i) {
210	    auto fut_ret = future_rets[i].get();
211	    ret = fut_ret != ge::SUCCESS ? fut_ret : ret;
212	    LLM_CHK_STATUS(fut_ret, "Failed to unlink clusters, index = %zu", i);
213	    rets.emplace_back(fut_ret);
214	  }
215	  return ret;
216	}
217	
218	void HixlTransferEngine::UnlinkAllClusters() {
219	  LLMLOGI("Begin to unlink all clusters.");
220	  engine_->Disconnect();
221	}
222	
223	ge::Status HixlTransferEngine::Link(std::string &cluster_name, const std::map<uint64_t, uint32_t> &cluster2rank,
224	                                    std::string &rank_table, uint64_t &comm_id) {
225	  (void)cluster_name;
226	  (void)cluster2rank;
227	  (void)rank_table;
228	  (void)comm_id;
229	  LLMLOGE(llm_datadist::LLM_FEATURE_NOT_ENABLED, "The feature is not supported.");
230	  return llm_datadist::LLM_FEATURE_NOT_ENABLED;
231	}
232	
233	ge::Status HixlTransferEngine::Unlink(uint64_t comm_id) {
234	  (void)comm_id;
235	  LLMLOGE(llm_datadist::LLM_FEATURE_NOT_ENABLED, "The feature is not supported.");
236	  return llm_datadist::LLM_FEATURE_NOT_ENABLED;
237	}
238	
239	ge::Status HixlTransferEngine::QueryRegisterMemStatus(uint64_t comm_id, RegisterMemoryStatus &status) {
240	  (void)comm_id;
241	  (void)status;
242	  LLMLOGE(llm_datadist::LLM_FEATURE_NOT_ENABLED, "The feature is not supported.");
243	  return llm_datadist::LLM_FEATURE_NOT_ENABLED;
244	}
245	
246	ge::Status HixlTransferEngine::SwitchRole(const std::string &role, const std::map<std::string, std::string> &options) {
247	  (void)role;
248	  const auto &port_iter = options.find(kLlmOptionListenPort);
249	  const auto &ip_iter = options.find(kLlmOptionListenIp);
250	  if (port_iter != options.cend() && ip_iter != options.cend()) {
251	    std::string ip = ip_iter->second;
252	    uint32_t port = 0U;
253	    LLM_CHK_STATUS_RET(LLMUtils::ToNumber(port_iter->second, port), "Option %s is invalid: [%s]", kLlmOptionListenPort,
254	                       port_iter->second.c_str());
255	    auto local_engine = ip + ":" + std::to_string(port);
256	    LLM_CHK_BOOL_RET_STATUS(local_engine == local_engine_, ge::LLM_FEATURE_NOT_ENABLED,
257	                            "listen ip info:%s is not the same with init listen ip info:%s.", local_engine.c_str(),
258	                            local_engine_.c_str());
259	  }
260	  return ge::SUCCESS;
261	}
262	}  // namespace llm
