36	
37	// Helper function to determine transfer type based on operation and memory types
38	TransferType DetermineTransferType(TransferOp operation, MemType local_mem_type, MemType remote_mem_type) {
39	  if (operation == TransferOp::READ) {
40	    if (local_mem_type == MemType::MEM_HOST && remote_mem_type == MemType::MEM_HOST) {
41	      return TransferType::kReadRH2H;
42	    }
43	    if (local_mem_type == MemType::MEM_HOST && remote_mem_type == MemType::MEM_DEVICE) {
44	      return TransferType::kReadRD2H;
45	    }
46	    if (local_mem_type == MemType::MEM_DEVICE && remote_mem_type == MemType::MEM_HOST) {
47	      return TransferType::kReadRH2D;
48	    }
49	    return TransferType::kReadRD2D;
50	  }
51	  // WRITE operation
